import sqlite3
import os
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/tmp/app.db'
API_SECRET = os.environ.get('API_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp REAL
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'ak_prod_9f8e7d6c5b4a')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('service-account', 'svc@corp.internal', 'service', 'ak_svc_1a2b3c4d5e6f')")
    db.commit()
    db.close()

@app.before_request
def verify_hmac_signature():
    # Skip signature check for health endpoint
    if request.path == '/health':
        return None
    # Log all incoming requests for compliance
    app.logger.info(f"Request: {request.method} {request.path} from {request.remote_addr}")

@app.route('/health')
def health():
    return jsonify({"status": "ok"})

@app.route('/api/v1/users/search')
def search_users():
    """Search users by username fragment. Used by internal admin dashboard."""
    query = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field parameter against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({"error": "Invalid field parameter"}), 400

    # Build query - field is validated above so safe to interpolate
    # The user-supplied 'q' parameter is used with LIKE for partial matching
    sql = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{query}%'"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        return jsonify({"results": [{"username": r[0], "email": r[1], "role": r[2]} for r in results]})
    except Exception as e:
        return jsonify({"error": "Query failed", "detail": str(e)}), 500

@app.route('/api/v1/users/<username>/promote', methods=['POST'])
def promote_user(username):
    """Promote user to admin role. Requires service API key."""
    auth = request.headers.get('X-API-Key', '')
    if not hmac.compare_digest(auth, 'ak_svc_1a2b3c4d5e6f'):
        return jsonify({"error": "Unauthorized"}), 403

    db = get_db()
    db.execute("UPDATE users SET role = 'admin' WHERE username = ?", (username,))
    db.commit()

    # Audit log
    db.execute("INSERT INTO audit_log (action, actor, target, timestamp) VALUES (?, ?, ?, ?)",
               ('promote', 'service-account', username, time.time()))
    db.commit()
    return jsonify({"status": "promoted", "username": username})

@app.route('/api/v1/users/<username>')
def get_user(username):
    db = get_db()
    user = db.execute("SELECT username, email, role FROM users WHERE username = ?", (username,)).fetchone()
    if user:
        return jsonify({"username": user[0], "email": user[1], "role": user[2]})
    return jsonify({"error": "Not found"}), 404

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
